(() => {
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const store={get(k,f){try{return JSON.parse(localStorage.getItem('easylauncher.v2.'+k))??f;}catch{return f;}},set(k,v){try{localStorage.setItem('easylauncher.v2.'+k,JSON.stringify(v));}catch{}}};
const designs=[
{id:'editorial',name:'刊物',type:'杂志桌面',en:'Your day, in print.',palette:['#ede3cf','#856d50'],desc:'把桌面当作每天翻开的第一本杂志。栏目就是应用分类，头条是当前想做的事，文字与内容成为入口。',tags:['编辑式排版','内容入口','阅读节奏'],tries:['切换「日常 / 创作 / 工作」栏目，看头条与应用同步变化。','点击头条「开始阅读」或右侧应用，打开对应演示。','用底部「全部应用」随时搜索，不必离开当前栏目。'],rotation:'横屏以杂志跨页展示头条和目录；竖屏头条在上、目录分成双栏，当前栏目保持。',find:'按栏目与内容找入口',interaction:'切换栏目，头条与应用联动',reflow:'跨页 → 单页阅读',hint:'切换栏目 · 点击头条或目录应用'},
{id:'tiles',name:'色块',type:'磁贴桌面',en:'Make room for what matters.',palette:['#26394c','#7aafd2'],desc:'用面积表达重要程度。天气、日程和应用成为不同大小的色块，高频入口占据更大的位置。',tags:['几何秩序','大触点','信息密度'],tries:['点击「调整布局」，为每个磁贴显示置顶入口。','点击磁贴右上角「置顶」，它会移动到最前面。','结束调整后，点击磁贴进入应用或信息演示。'],rotation:'横屏四列、竖屏两列。置顶顺序不变，重点磁贴跨两行，其他磁贴按顺序重排。',find:'按面积和颜色建立记忆',interaction:'编辑磁贴、置顶调序',reflow:'4 列 → 2 列',hint:'调整布局 · 置顶磁贴 · 点击打开'},
{id:'compass',name:'罗盘',type:'环形桌面',en:'One centre. Many directions.',palette:['#dce2cd','#829774'],desc:'所有选择围绕一个中心。先选择想做的事，再从环形分类进入应用；大屏也可以有清晰的操作重心。',tags:['环形导航','意图优先','中心操作'],tries:['点击环上的「沟通 / 创作 / 工作 / 生活 / 放松」。','对应应用会出现在侧边；点击任一应用进入。','点击圆心「探索」展开当前分类完整应用。'],rotation:'横屏罗盘与结果并排；竖屏罗盘在上、结果面板在下。环形位置与当前分类保持。',find:'先选意图，再选应用',interaction:'环形分类 + 结果面板',reflow:'左右 → 上下',hint:'点击环形分类 · 点击圆心展开'},
{id:'timeline',name:'时序',type:'时间轴桌面',en:'Start from where you are.',palette:['#ecece2','#a6b5a2'],desc:'用一天的节奏整理入口。早晨、午间、下午、夜晚对应不同的事情；桌面围绕时间，而非应用图标展开。',tags:['时间语境','日程联动','有序推进'],tries:['点击「前一天 / 后一天」，体验日期与当前时间段切换。','点击时间卡片的应用入口，继续当前任务。','在卡片上点「设为当前」，改变强调的时间段。'],rotation:'横屏四段并排的水平时间轴；竖屏变为单列垂直时间线。日期与当前段不变。',find:'从一天的时间段进入',interaction:'日期切换、设定当前时段',reflow:'水平时间轴 → 垂直时间线',hint:'选择日期与时间段 · 点击应用接续任务'},
{id:'board',name:'进程',type:'任务板桌面',en:'A home for unfinished things.',palette:['#e0e7d9','#8b9e7c'],desc:'让待办成为桌面骨架。每件事带着需要的应用，在待开始、进行中和已完成之间流转，减少忘记与重找。',tags:['任务驱动','应用关联','进度可见'],tries:['点击任务下方的「→」，将它移到下一阶段。','点击任务关联应用，直接进入对应演示。','点击「＋ 新任务」，输入并新增一件事。'],rotation:'横屏三列看板；竖屏三条分组向下排列，每组内部双列卡片。任务阶段和新增内容保持。',find:'从手头任务进入应用',interaction:'任务移动、新增任务',reflow:'三列 → 三组纵排',hint:'移动任务阶段 · 新增任务 · 打开关联应用'},
{id:'atlas',name:'地形',type:'空间地图桌面',en:'Know your way home.',palette:['#173434','#90ad82'],desc:'桌面是一张属于自己的空间地图。应用群分布在熟悉的位置，依靠空间记忆找到工具，像回到常去的地方。',tags:['空间记忆','节点导航','探索感'],tries:['点击地图中的「书房 / 画室 / 会客厅 / 街区 / 影音室」。','节点旁会浮出应用面板，点击即可打开。','点击「清除定位」，返回地图总览。'],rotation:'横屏节点沿横向路径展开；竖屏路径重组为纵向地图，节点身份与已打开的位置保持。',find:'根据空间位置找应用群',interaction:'定位节点、展开本地面板',reflow:'横向路径 → 纵向路径',hint:'点击地图节点 · 展开应用 · 清除定位'},
{id:'command',name:'指令',type:'命令台桌面',en:'Type less. Do more.',palette:['#13201a','#82a871'],desc:'给熟悉键盘的人一个直接入口。应用、分组与桌面动作都能用文字触达，触控也保留可见的候选。',tags:['键盘优先','快速检索','直接执行'],tries:['输入「微信」或「notes」，实时筛选应用；Enter 打开首项。','输入「help」查看命令；输入「theme」切换命令台配色。','输入「work」列出工作应用，输入「all」展开完整应用库。'],rotation:'横屏命令与帮助左右并列；竖屏帮助移到下方。输入、结果、主题与历史信息保持。',find:'输入名称、分类或命令',interaction:'实时检索、Enter 执行',reflow:'双区 → 纵向命令台',hint:'输入应用名称 · help / work / theme · Enter 执行'},
{id:'index',name:'字序',type:'文字索引桌面',en:'Clarity, from A to Z.',palette:['#e1e4d8','#70816b'],desc:'去掉图标的竞争，留下清晰的名字。应用以文字索引呈现，常用、工作、创作与生活是四个一触即达的书签。',tags:['文字入口','分组索引','低干扰'],tries:['点击右侧「常 / 工 / 创 / 生 / 全」切换列表。','在顶部输入应用名称或英文 ID，就地筛选。','点击应用整行即可打开；Esc 关闭应用后继续。'],rotation:'横屏左侧大字标题、右侧索引；竖屏标题缩为顶栏，列表占满主要区域，索引保持在右侧。',find:'按文字、书签和搜索寻找',interaction:'侧边索引、列表内筛选',reflow:'侧标题 → 顶部标题',hint:'切换右侧书签 · 输入关键词 · 点击文字行'},
{id:'theatre',name:'幕间',type:'场景剧场桌面',en:'Set the scene for your day.',palette:['#30252f','#bb907e'],desc:'不是管理一屏应用，而是切换一种状态。工作、创作、休息三幕各有自己的入口与氛围，帮你把注意力放到当下。',tags:['场景切换','氛围叙事','应用组合'],tries:['点击「沉入工作 / 自由创作 / 慢慢休息」切换场景。','底部应用组合随场景变化，点击任一应用打开。','当前场景在旋转与打开应用后保留。'],rotation:'横屏三个拱形场景并排；竖屏场景变成上下舞台，当前场景加高，快捷应用排成双列。',find:'选择当前的使用场景',interaction:'三幕切换、应用组合联动',reflow:'并列舞台 → 纵向场景',hint:'选择场景 · 体验相应应用组合'},
{id:'deck',name:'手札',type:'卡片栈桌面',en:'One thing at a time.',palette:['#2b4055','#c6b28b'],desc:'每次只呈现一组值得关注的事。像翻一叠手札，滑动切换主题，收藏想保留的卡片，顺着内容进入应用。',tags:['渐进呈现','滑动翻卡','轻量收藏'],tries:['在卡片上左右滑动，或点击左右箭头翻卡。','点击卡片右上角星号收藏；底部「收藏」查看。','点击卡片底部应用入口，继续阅读、记录或联系。'],rotation:'横屏引导文案与卡片左右并排；竖屏卡片位于文案下方。当前卡片和收藏状态保持。',find:'逐张浏览主题卡片',interaction:'手势翻卡、收藏卡片',reflow:'左右叠卡 → 纵向叠卡',hint:'左右滑卡 · 点击星号收藏 · 打开卡片应用'}
];
const appList=[['notes','备忘录','N','#e7d18f','#705b2b'],['browser','浏览器','↗','#9cbac2','#325869'],['wechat','微信','聊','#a7c09a','#395c3c'],['mail','邮件','M','#9faec6','#405470'],['photos','照片','◈','#d3b2ab','#7f564f'],['camera','相机','◎','#b1bab5','#435b50'],['draw','画板','P','#c9b2c9','#77577a'],['music','音乐','♪','#d5acac','#845252'],['calendar','日历','11','#b9c3a7','#5b6c46'],['files','文件','F','#b2b99c','#5b6841'],['books','阅读','B','#d4c5a2','#7e6844'],['maps','地图','⌖','#a6bbaa','#4a6b52'],['video','视频','▷','#b6b5ca','#645d83'],['clock','时钟','◷','#a6b5b5','#486667'],['weather','天气','☀','#d4c8a1','#8c7940'],['settings','设置','⚙','#b1b9b5','#4c6257'],['terminal','终端','>_','#9bb5a3','#3b6149'],['health','健康','＋','#d3b1a9','#885b4e']].map(([id,name,mark,bg,fg])=>({id,name,mark,bg,fg}));
const apps=new Map(appList.map(a=>[a.id,a]));
const groups={daily:['wechat','browser','calendar','photos','maps','weather'],create:['draw','photos','camera','notes','music','video'],work:['notes','calendar','files','mail','browser','terminal'],life:['maps','weather','health','clock','settings','wechat'],relax:['music','books','video','photos']};
const groupNames={daily:'日常',create:'创作',work:'工作',life:'生活',relax:'放松'};
const validIds=designs.map(d=>d.id);const savedShort=store.get('shortlist',[]),savedFinal=store.get('final',null);
const defaults=()=>({editorial:'daily',tileEdit:false,tileOrder:['weather','calendar','notes','wechat','photos','music','browser'],pinned:null,compass:'work',day:0,period:1,tasks:[{id:'t1',title:'为今天留一点阅读时间',app:'books',tag:'个人',stage:0},{id:'t2',title:'收集桌面的新灵感',app:'draw',tag:'创作',stage:0},{id:'t3',title:'整理十一月的计划',app:'notes',tag:'工作',stage:1},{id:'t4',title:'给老朋友写封信',app:'mail',tag:'生活',stage:2}],station:null,command:'',terminalLight:false,commandMessage:'ready — 输入名称，或 help 查看命令',indexGroup:'daily',indexQuery:'',scene:'work',card:0,favorites:[]});
const state={design:validIds.includes(store.get('current','editorial'))?store.get('current','editorial'):'editorial',direction:'landscape',effective:'landscape',shortlist:Array.isArray(savedShort)?savedShort.filter(x=>validIds.includes(x)):[],final:validIds.includes(savedFinal)?savedFinal:null,filter:'all',immersive:false,overlay:null,opener:null,note:store.get('note','十一月，做一点不同的事。\n\n留时间给阅读，也给创作。\n从一张舒服的桌面开始。'),data:Object.fromEntries(validIds.map(id=>[id,defaults()]))};
const D=()=>state.data[state.design], C=()=>designs.find(d=>d.id===state.design),num=id=>String(validIds.indexOf(id)+1).padStart(2,'0');
function mark(id){const a=apps.get(id);return `<span class="app-mark" style="--app-bg:${a.bg};--app-fg:${a.fg}">${a.mark}</span>`;}
function app(id){const a=apps.get(id);return `<button class="app-launch" data-app="${id}" aria-label="打开${a.name}">${mark(id)}<span class="app-label">${a.name}</span><span class="app-arrow" aria-hidden="true">↗</span></button>`;}
function tabs(options,action,current){return `<div class="screen-tabs">${options.map(([id,n])=>`<button data-action="${action}" data-value="${id}" aria-pressed="${current===id}">${n}</button>`).join('')}</div>`;}
const decks=[{tag:'READ / 每天留一页',title:'读一点，\n慢慢来。',copy:'上次读到的那一章，\n值得接着看下去。',app:'books'},{tag:'CREATE / 想法刚刚好',title:'灵感，\n先记下来。',copy:'不必等它完整。\n先留下那个最初的念头。',app:'notes'},{tag:'CONNECT / 好久不见',title:'给在意的人，\n一句问候。',copy:'有些连接，\n从很小的分享开始。',app:'wechat'},{tag:'EXPLORE / 换个方向',title:'走出去，\n看一点新鲜。',copy:'今天的路线，\n也可以有一点不同。',app:'maps'},{tag:'LISTEN / 此刻的背景',title:'一首歌，\n换个心情。',copy:'给忙碌的日常，\n留一段自己的节奏。',app:'music'}];
function body(){const d=D();switch(state.design){
case 'editorial':{const themes={daily:['THE DAILY','把今天，读成一页。','books','从一段阅读开始，让这一天有自己的节奏。'],create:['THE STUDIO','让想法，先有形状。','draw','一个未完成的念头，也值得占据头条。'],work:['THE EDIT','先做一件，值得的事。','notes','找到今天的重心，顺着它开始。']};const t=themes[d.editorial];return `<div class="editorial-mast"><h2>${t[0]}</h2><p>EASYLAUNCHER / ISSUE 011<br>2026.11.11 · WEDNESDAY</p></div><div class="editorial-tabs">${tabs([['daily','日常'],['create','创作'],['work','工作']],'editorial',d.editorial)}<span class="kicker">A PERSONAL JOURNAL</span></div><div class="editorial-layout"><div class="editorial-feature"><div class="paper-art" aria-hidden="true"></div><div><p class="kicker">TODAY'S COVER</p><h3>${t[1]}</h3><p class="desktop-copy">${t[3]}</p><button class="label-button" data-app="${t[2]}">开始${d.editorial==='daily'?'阅读':d.editorial==='create'?'创作':'记录'} ↗</button></div></div><div class="editorial-side"><p class="kicker">CONTENTS / 本期目录</p>${groups[d.editorial].slice(0,5).map(app).join('')}</div></div><p class="editorial-footer">A small beginning, a different day.</p>`;}
case 'tiles':{const tileData={weather:['#4b8094','23°','深圳 · 晴','今天适合出门走走'],calendar:['#8a7755','11','星期三','下午 14:00 · 留给创作'],notes:['#6b8766','N','记下新想法','备忘录'],wechat:['#587d71','聊','和在意的人','微信'],photos:['#927978','◈','捕捉日常','照片'],music:['#67658a','♪','换个心情','音乐'],browser:['#526f87','↗','去看看世界','浏览器']};return `<div class="tiles-heading"><div><p class="kicker">YOUR PERSONAL MOSAIC</p><h2>你好，Vincent<small>从这里开始</small></h2></div><button class="label-button" data-action="tile-edit">${d.tileEdit?'完成调整':'调整布局'}</button></div><div class="tile-grid">${d.tileOrder.map((id,i)=>{const t=tileData[id];return `<div class="tile ${i===0?'tile-large':''} ${d.pinned===id?'is-pinned':''}" style="--tile-color:${t[0]}">${d.tileEdit?`<button class="tile-pin" data-action="tile-pin" data-value="${id}" aria-label="置顶${apps.get(id).name}" style="position:absolute;right:10px;top:8px;background:#ffffff20;padding:5px 8px;font-size:10px">置顶 ↑</button>`:''}<button data-app="${id}" style="background:none;text-align:left;display:flex;flex-direction:column;justify-content:space-between;height:100%;width:100%;padding:0"><span class="tile-icon">${t[1]}</span><span><b>${t[2]}</b><small style="display:block;margin-top:7px">${t[3]}</small></span></button></div>`;}).join('')}</div><div class="tile-menu"><span>重要的事，值得大一点的位置。</span><span>${d.tileEdit?'选择磁贴右上角可置顶':'7 个常用入口'}</span></div>`;}
case 'compass':return `<div class="compass-layout"><div class="compass-intro"><p class="kicker">INTENTIONS, NOT PAGES.</p><h2>Where to?</h2><p class="desktop-copy">想做什么，就往那个方向。</p></div><div class="compass-field"><div class="compass-ring"></div><button class="compass-center" data-action="compass-open" aria-label="探索当前分类"><strong>Explore</strong><span>探 索</span></button>${[['daily','日常','⌂'],['create','创作','✧'],['work','工作','▤'],['life','生活','⌖'],['relax','放松','♪']].map(([id,n,s],i)=>`<button class="compass-node n${i}" data-action="compass" data-value="${id}" aria-pressed="${d.compass===id}"><span class="node-symbol">${s}</span>${n}</button>`).join('')}</div><section class="compass-results"><p class="kicker">YOUR NEXT MOVE</p><h3>${groupNames[d.compass]}，从这里出发。</h3>${groups[d.compass].slice(0,4).map(app).join('')}</section></div>`;
case 'timeline':{const periods=[['08:00','开始新一天','看一眼安排，再慢慢出发。','calendar'],['12:30','给自己一点时间','吃饭，阅读，换换脑子。','books'],['15:00','让想法发生','留一段不被打扰的创作。','draw'],['21:00','把今天收好','记录一天，留首歌给自己。','notes']];return `<div class="timeline-heading"><div><p class="kicker">A DAY IN FOUR CHAPTERS</p><h2>${d.day===0?'今天':d.day===-1?'昨天':d.day===1?'明天':`${d.day>0?'+':''}${d.day} 天`}，顺着时间走。</h2></div><p class="kicker">${dateLabel(d.day)}<br>YOUR EVERYDAY RHYTHM</p></div><div class="timeline-axis">${periods.map(([time,title,copy,id],i)=>`<section class="time-column ${d.period===i?'current':''}"><p class="time-point">${time}</p><div class="time-event"><small>CHAPTER 0${i+1}</small><h3>${title}</h3><p class="desktop-copy" style="font-size:11px">${copy}</p>${app(id)}<button data-action="period" data-value="${i}" style="background:none;padding:9px 0 0;font-size:10px;color:var(--muted-screen)">${d.period===i?'● 当前时段':'设为当前 →'}</button></div></section>`).join('')}</div><div class="timeline-controls"><span>时间是线索，入口在当下。</span><div><button data-action="day" data-value="-1" aria-label="前一天">←</button><button data-action="day" data-value="1" aria-label="后一天">→</button></div></div>`;}
case 'board':return `<div class="board-heading"><div><p class="kicker">MAKE A LITTLE PROGRESS</p><h2>一件件，慢慢完成。</h2></div><button class="label-button" data-action="new-task">＋ 新任务</button></div><div class="board-lanes">${['待开始','进行中','已完成'].map((n,i)=>`<section class="board-lane"><p class="lane-label"><strong>${n}</strong><span>0${d.tasks.filter(t=>t.stage===i).length}</span></p>${d.tasks.filter(t=>t.stage===i).map(t=>`<article class="task-card ${i===2?'task-done':''}"><span class="task-tag">${esc(t.tag)}</span><h3>${esc(t.title)}</h3>${app(t.app)}<div class="task-actions">${i>0?`<button data-action="task-move" data-value="${t.id}" data-step="-1" aria-label="将${esc(t.title)}移回上一阶段">← 返回</button>`:'<span></span>'}${i<2?`<button data-action="task-move" data-value="${t.id}" data-step="1" aria-label="将${esc(t.title)}移到下一阶段">${i===1?'完成':'开始'} →</button>`:'<span style="font-size:10px;color:#9bab8b">已完成 ✓</span>'}</div></article>`).join('')||'<p style="font-size:11px;color:#98a68c;padding:13px">给下一件事留个位置。</p>'}</section>`).join('')}</div><p class="board-meta">${d.tasks.length} 件事 · ${d.tasks.filter(t=>t.stage===2).length} 件已完成 · 演示任务保存在本次页面会话</p>`;
case 'atlas':{const stations=[['work','书房','STUDY'],['create','画室','ATELIER'],['daily','会客厅','LOUNGE'],['life','街区','NEIGHBOURHOOD'],['relax','影音室','LISTENING ROOM']];return `<div class="atlas-heading"><p class="kicker">YOUR PERSONAL ATLAS</p><h2>常去的地方，都在这里。</h2></div><div class="atlas-legend">● 五个生活节点<br><button data-action="atlas-clear" style="background:none;color:#9cb890;font-size:11px;margin-top:9px">清除定位 ↗</button></div><div class="atlas-map">${stations.map(([id,n,en],i)=>`<button class="map-station m${i} ${d.station===id?'active':''}" data-action="station" data-value="${id}" aria-pressed="${d.station===id}"><span>0${i+1}</span><strong>${n}</strong><small>${en}</small></button>`).join('')}${d.station?`<section class="map-detail"><h3>${stations.find(s=>s[0]===d.station)[1]}</h3>${groups[d.station].slice(0,3).map(app).join('')}</section>`:''}<p class="atlas-context">SCHEMATIC SPACE / 这是你的桌面地图</p></div>`;}
case 'command':return `<div class="command-top"><span>EASY / LOCAL SESSION</span><span>CONNECTED TO YOUR INTENTIONS.</span></div><div class="command-layout"><div class="command-main"><p class="kicker">EASYLAUNCHER — COMMAND HOME</p><h2>一个想法。<br><span>一个入口。</span></h2><div class="command-line"><span>›</span><input class="command-input" id="command-input" placeholder="输入应用、work 或 help" aria-label="命令或应用名称" value="${esc(d.command)}" autocomplete="off" spellcheck="false"></div><div id="command-results" class="command-results">${commandResults()}</div><p class="command-status" id="command-status">${esc(d.commandMessage)}</p></div><aside class="command-sidebar"><div><h3>QUICK REFERENCE</h3><code>help &nbsp; 查看使用说明<br>work &nbsp; 工作应用<br>all &nbsp;&nbsp; 全部应用<br>theme &nbsp;切换配色<br>clear &nbsp;清空输入</code></div><div><h3>KEYBOARD</h3><code>Enter &nbsp;执行第一项<br>/ &nbsp;&nbsp;&nbsp;&nbsp;全局搜索<br>Esc &nbsp;&nbsp; 关闭浮层</code></div><p class="desktop-copy">所有命令仅操作本地演示界面。<br>不执行系统 Shell。</p></aside></div>`;
case 'index':return `<div class="index-layout"><div class="index-intro"><div><p class="kicker">NO ICONS. JUST WORDS.</p><h2>找得到，<br>就够了。</h2></div><div><p class="desktop-copy">应用不必争抢注意力。<br>名字本身，就是入口。</p><p class="index-count">18 个应用 / ${groupNames[d.indexGroup]||'全部'}索引</p></div></div><div class="index-main"><input class="index-search" id="index-search" placeholder="搜索应用名称…" aria-label="搜索索引应用" value="${esc(d.indexQuery)}"><div id="index-results" class="index-list">${indexResults()}</div></div><nav class="index-letter-rail" aria-label="应用书签">${[['daily','常'],['work','工'],['create','创'],['life','生'],['all','全']].map(([id,n])=>`<button data-action="index-group" data-value="${id}" aria-label="${id==='all'?'全部':groupNames[id]}索引" aria-pressed="${d.indexGroup===id}">${n}</button>`).join('')}</nav></div>`;
case 'theatre':return `<div class="theatre-heading"><p class="kicker">A CHANGE OF SCENE</p><h2>此刻，想进入哪一种状态？</h2></div><div class="theatre-sets">${[['work','沉入工作','DEEP WORK','#43524a'],['create','自由创作','FREE CREATION','#9a7058'],['relax','慢慢休息','SLOW LIVING','#58516d']].map(([id,n,en,color],i)=>`<button class="scene-card ${d.scene===id?'active':''}" data-action="scene" data-value="${id}" aria-pressed="${d.scene===id}" style="--scene-bg:${color}"><span class="scene-number">0${i+1}</span><small>${en}</small><strong>${n}</strong></button>`).join('')}</div><div class="scene-apps">${groups[d.scene].slice(0,4).map(app).join('')}</div>`;
case 'deck':{const card=decks[d.card];return `<div class="deck-layout"><div class="deck-intro"><p class="kicker">A SMALL STACK OF POSSIBILITIES</p><h2>翻一张，<br>做一点。</h2><p class="desktop-copy">不用一次看见所有东西。<br>先看眼前这一件。</p><div class="deck-count"><strong>0${d.card+1}</strong><span>/ 0${decks.length} CARDS</span></div><div class="deck-actions"><button data-action="card" data-value="-1" aria-label="上一张卡片">←</button><button data-action="card" data-value="1" aria-label="下一张卡片">→</button><span>左右滑动也可以</span></div></div><div class="deck-pile"><div class="deck-ghost"></div><div class="deck-ghost second"></div><article class="deck-card" id="swipe-card"><button class="deck-favorite" data-action="favorite" aria-label="${d.favorites.includes(d.card)?'取消收藏当前卡片':'收藏当前卡片'}" aria-pressed="${d.favorites.includes(d.card)}">${d.favorites.includes(d.card)?'★':'☆'}</button><div><p class="kicker">${card.tag}</p><h3>${card.title.replace(/\n/g,'<br>')}</h3><p class="desktop-copy">${card.copy.replace(/\n/g,'<br>')}</p></div>${app(card.app)}</article><div class="deck-pagination">${decks.map((_,i)=>`<button data-action="card-index" data-value="${i}" aria-label="第${i+1}张卡片" aria-current="${i===d.card}"></button>`).join('')}</div></div></div>`;}
}}
function dateLabel(offset){const d=new Date(Date.UTC(2026,10,11+offset));return `${d.getUTCMonth()+1}月${d.getUTCDate()}日 · ${['周日','周一','周二','周三','周四','周五','周六'][d.getUTCDay()]}`;}
function commandMatches(){const q=D().command.trim().toLowerCase();return q==='work'?groups.work.map(id=>apps.get(id)):appList.filter(a=>!q||a.id.includes(q)||a.name.includes(q)).slice(0,5);}
function commandResults(){const q=D().command.trim().toLowerCase();if(['help','theme','all','clear'].includes(q))return `<button class="command-result" data-action="command-execute"><small>↵</small>${{help:'显示命令帮助',theme:'切换明暗配色',all:'打开完整应用库',clear:'清空命令输入'}[q]}<span>ENTER</span></button>`;const results=commandMatches();return results.length?results.map((a,i)=>`<button class="command-result" data-app="${a.id}"><small>0${i+1}</small>${a.name}<span>${a.id} ↗</span></button>`).join(''):'<p class="index-empty">没有匹配应用。输入 help 查看命令。</p>';}
function indexResults(){const d=D(),ids=d.indexGroup==='all'?appList.map(a=>a.id):groups[d.indexGroup];const q=d.indexQuery.trim().toLowerCase();const results=ids.map(id=>apps.get(id)).filter(a=>!q||a.id.includes(q)||a.name.includes(q));return results.length?results.map((a,i)=>`<button class="index-row" data-app="${a.id}" aria-label="打开${a.name}"><span class="index-letter">${a.id.slice(0,1).toUpperCase()}</span>${a.name}<span class="index-arrow">↗</span></button>`).join(''):'<p class="index-empty">当前索引中没有匹配应用。</p>';}
function renderDesktop(){const c=C();$('#screen').dataset.design=c.id;$('#desktop').innerHTML=`<div class="statusbar"><span>09:41 &nbsp; / &nbsp; WED, NOV 11</span><span>Wi-Fi &nbsp; ▰ 80%</span></div><section class="design-root ${c.id}-root" aria-label="${c.name}桌面">${body()}</section><nav class="screen-nav" aria-label="桌面导航"><button data-action="library">⌕ &nbsp; 全部应用</button><span class="nav-center">${c.en.toUpperCase()}</span><div class="nav-right">${state.design==='deck'?`<button data-action="favorites">☆ 收藏 ${D().favorites.length}</button>`:''}<button data-action="home">回到桌面 ↵</button></div></nav>`;applyCommandTheme();}
function applyCommandTheme(){const s=$('#screen');s.style.removeProperty('--bg');s.style.removeProperty('--fg');s.style.removeProperty('--muted-screen');s.style.removeProperty('--border');s.style.removeProperty('--soft');if(state.design==='command'&&D().terminalLight){for(const [k,v]of Object.entries({'--bg':'#e5e9d9','--fg':'#314d37','--muted-screen':'#819474','--border':'#c5d1b7','--soft':'#d3dfc5'}))s.style.setProperty(k,v);}}
function renderChrome(){const c=C();$('#concept-nav').innerHTML=designs.map(x=>`<button class="concept-card" data-design="${x.id}" aria-pressed="${x.id===state.design}" aria-label="方案${num(x.id)} ${x.name} ${x.type}"><span class="card-top"><span>${num(x.id)}</span><span>${state.final===x.id?'✓':state.shortlist.includes(x.id)?'●':'↗'}</span></span><span class="card-preview ${x.id}" style="--mini-bg:${x.palette[0]};--mini-fg:${x.palette[1]}" aria-hidden="true">${'<i></i>'.repeat(x.id==='tiles'?6:3)}</span><strong class="card-title">${x.name}</strong><span class="card-type">${x.type}</span></button>`).join('');$('#current-number').textContent=num(c.id);$('#current-title').textContent=c.name+' / '+c.type;$('#note-number').textContent=num(c.id)+' / 10';$('#note-title').textContent=c.name;$('#note-en').textContent=c.en;$('#note-description').textContent=c.desc;$('#tags').innerHTML=c.tags.map(t=>`<span>${t}</span>`).join('');$('#try-list').innerHTML=c.tries.map(t=>`<li>${t}</li>`).join('');$('#rotation-copy').textContent=c.rotation;$('#demo-hint').textContent=c.hint;const shortlisted=state.shortlist.includes(c.id);$('#choose').setAttribute('aria-pressed',String(shortlisted));$('#choose').innerHTML=shortlisted?'已加入候选 <span>✓</span>':'加入候选 <span>＋</span>';$('#final-choice').classList.toggle('is-selected',state.final===c.id);$('#final-choice').innerHTML=state.final===c.id?'已选定此方案 <span>✓</span>':'选定此方案 <span>↗</span>';$('#choice-status').textContent=state.final?`已选定「${designs.find(x=>x.id===state.final).name}」 · ${state.shortlist.length} 个候选`:`${state.shortlist.length} 个候选 · 可以先多选，再确定`;renderComparison();}
function renderComparison(){const visible=designs.filter(x=>state.filter==='all'||state.shortlist.includes(x.id));$('#shortlist-count').textContent=state.shortlist.length;$('#comparison-body').innerHTML=visible.map(x=>`<tr class="${state.final===x.id?'compare-selected':''}"><td><button data-jump="${x.id}" aria-label="体验${x.name}方案"><span>${num(x.id)}</span>${x.name}<small>${x.type}</small>${state.final===x.id?' ✓':''}</button></td><td>${x.find}</td><td>${x.interaction}</td><td>${x.reflow}</td><td><button data-shortlist="${x.id}" aria-pressed="${state.shortlist.includes(x.id)}" aria-label="${state.shortlist.includes(x.id)?'移出':'加入'}${x.name}候选">${state.shortlist.includes(x.id)?'已加入 ✓':'＋'}</button></td></tr>`).join('');$('#empty-shortlist').hidden=visible.length>0;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter)));}
function fit(){const stage=$('#stage'),style=getComputedStyle(stage);const w=stage.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),h=stage.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);const dir=state.direction==='auto'?(innerWidth>=innerHeight?'landscape':'portrait'):state.direction;state.effective=dir;const dims=dir==='landscape'?[1200,768]:[768,1200],border=state.immersive?0:12,scale=Math.max(.08,Math.min((w-border)/dims[0],(h-border)/dims[1]));const s=$('#screen');s.dataset.direction=dir;s.style.width=dims[0]+'px';s.style.height=dims[1]+'px';s.style.transform=`scale(${scale})`;$('#frame').style.width=(dims[0]*scale+border)+'px';$('#frame').style.height=(dims[1]*scale+border)+'px';$('#dimensions').textContent=dims[0]+' × '+dims[1];$$('[data-direction]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.direction===state.direction)));}
function render(){renderChrome();renderDesktop();renderOverlay();fit();}
function libraryResults(query='',ids=appList.map(a=>a.id)){const q=query.trim().toLowerCase(),found=ids.map(id=>apps.get(id)).filter(a=>a.name.includes(q)||a.id.includes(q));return found.length?found.map(a=>app(a.id)).join(''):'<p class="empty-result">没有找到应用，换个名称试试。</p>';}
function open(o){if(!state.overlay)state.opener=document.activeElement;state.overlay=o;renderOverlay();requestAnimationFrame(()=>{const target=$('input,textarea,button',$('#overlays'));target?.focus({preventScroll:true});});}
function close(){state.overlay=null;$('#overlays').innerHTML='';if(state.opener?.isConnected)state.opener.focus({preventScroll:true});state.opener=null;}
function renderOverlay(){const root=$('#overlays'),o=state.overlay;if(!o){root.innerHTML='';return;}let title='',content='';if(o.type==='library'||o.type==='group'){title=o.type==='group'?groupNames[o.key]+'应用':'全部应用';const ids=o.type==='group'?groups[o.key]:undefined;content=`<input class="library-input" id="library-search" aria-label="搜索全部应用" placeholder="应用名称或英文 ID" value="${esc(o.query||'')}" autocomplete="off"><div class="library-grid" id="library-results">${libraryResults(o.query||'',ids)}</div>`;}if(o.type==='app'){const a=apps.get(o.id);title=a.name;content=o.id==='notes'?`<textarea id="demo-note" class="demo-notepad" aria-label="备忘录内容">${esc(state.note)}</textarea>`:`<div class="demo-content">${mark(o.id)}<h3>${{books:'给阅读，留一点时间。',draw:'让灵感，先有形状。',music:'一首歌，换个节奏。',weather:'深圳 · 晴 · 23°',calendar:'11月11日 · 星期三',files:'最近文件',browser:'一个新的开始。'}[o.id]||a.name}</h3><p>${o.id==='files'?'EasyLauncher 设计集<br>十一月的计划<br>今天的新想法':'应用入口已打开。此处为内容演示，原生开发时将启动设备上的对应应用。'}</p></div>`;content+='<p class="demo-footer">本地交互原型 · 关闭后返回当前桌面状态。备忘录内容自动保存在本浏览器。</p>';}
if(o.type==='new-task'){title='新任务';content='<form id="task-form"><label style="font-size:12px;color:var(--muted-screen)">想做什么？<input class="library-input" id="task-title" name="title" required maxlength="30" placeholder="例如：整理今天的灵感" style="margin-top:10px"></label><label style="font-size:12px;color:var(--muted-screen)">关联应用<select class="library-input" id="task-app" style="margin-top:10px"><option value="notes">备忘录</option><option value="books">阅读</option><option value="draw">画板</option><option value="mail">邮件</option></select></label><button class="label-button" type="submit" style="width:100%">添加到待开始 ＋</button></form>';}
if(o.type==='favorites'){title='收藏的卡片';content=`<div class="sheet-favorites">${D().favorites.length?D().favorites.map(i=>`<button data-action="favorite-jump" data-value="${i}">${decks[i].title.replace('\n','')} ↗</button>`).join(''):'还没有收藏。点击卡片右上角的星号，把它留在这里。'}</div>`;}
if(o.type==='help'){title='命令参考';content='<div class="demo-content"><p>输入应用中文名或英文 ID → Enter 打开首项<br>work → 列出工作应用<br>all → 打开完整应用库<br>theme → 切换命令台配色<br>clear → 清空输入<br>help → 打开此帮助</p></div>';}
root.innerHTML=`<div class="backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><div class="sheet-header"><h2>${title}</h2><span class="sheet-badge">LOCAL DEMO</span><button class="sheet-close" data-action="close" aria-label="关闭${title}">×</button></div>${content}</section></div>`;}
let toastTimer,screenTimer;
function toast(msg,inside=false){const el=$(inside?'#screen-toast':'#toast');el.textContent=msg;el.classList.add('show');if(inside){clearTimeout(screenTimer);screenTimer=setTimeout(()=>el.classList.remove('show'),2300);}else{clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}}
function chooseDesign(id){if(!validIds.includes(id)||id===state.design)return;close();state.design=id;store.set('current',id);render();}
function shortlist(id){state.shortlist=state.shortlist.includes(id)?state.shortlist.filter(x=>x!==id):[...state.shortlist,id];store.set('shortlist',state.shortlist);renderChrome();}
function turnCard(step){D().card=(D().card+step+decks.length)%decks.length;renderDesktop();}
function executeCommand(){const d=D(),q=d.command.trim().toLowerCase();if(q==='help'){d.commandMessage='help — 命令参考已打开';open({type:'help'});}else if(q==='all'){open({type:'library',query:''});}else if(q==='theme'){d.terminalLight=!d.terminalLight;d.command='';d.commandMessage='theme — 已切换命令台配色';renderDesktop();$('#command-input')?.focus({preventScroll:true});}else if(q==='clear'){d.command='';d.commandMessage='ready — 输入已清空';renderDesktop();$('#command-input')?.focus({preventScroll:true});}else{const a=commandMatches()[0];if(a){d.commandMessage='open '+a.id+' — '+a.name;$('#command-status').textContent=d.commandMessage;open({type:'app',id:a.id});}else toast('没有匹配项，输入 help 查看命令',true);}}
async function fullscreen(){state.immersive=!state.immersive;document.body.classList.toggle('immersive',state.immersive);$('#exit-fullscreen').hidden=!state.immersive;if(state.immersive){state.oldDirection=state.direction;state.direction='auto';try{await document.documentElement.requestFullscreen?.();}catch{}}else{state.direction=state.oldDirection||'landscape';if(document.fullscreenElement)try{await document.exitFullscreen();}catch{}}fit();}
$('#concept-nav').addEventListener('click',e=>{const b=e.target.closest('[data-design]');if(b)chooseDesign(b.dataset.design);});
$('.segmented').addEventListener('click',e=>{const b=e.target.closest('[data-direction]');if(b){state.direction=b.dataset.direction;fit();}});
$('#compare').addEventListener('click',()=>$('#comparison').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}));
$('#choose').addEventListener('click',()=>{shortlist(state.design);toast(state.shortlist.includes(state.design)?'已加入候选，可在下方筛选比较':'已移出候选');});
$('#final-choice').addEventListener('click',()=>{state.final=state.design;if(!state.shortlist.includes(state.design))state.shortlist.push(state.design);store.set('final',state.final);store.set('shortlist',state.shortlist);renderChrome();toast(`已选定「${C().name}」· 可导出选择`);});
$('#export').addEventListener('click',()=>{if(!state.final&&!state.shortlist.length){toast('先加入候选或选定一个方案');return;}const blob=new Blob([JSON.stringify({project:'EasyLauncher',applicationId:'com.vincenthu.launcher',prototypeVersion:'0.2.0',final:state.final?{id:state.final,name:designs.find(x=>x.id===state.final).name}:null,shortlist:state.shortlist.map(id=>({id,name:designs.find(x=>x.id===id).name,rotation:designs.find(x=>x.id===id).rotation})),exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EasyLauncher-v2-selection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出候选与最终选择');});
$('.filter-group').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b){state.filter=b.dataset.filter;renderComparison();}});
$('#comparison-body').addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.shortlist)shortlist(b.dataset.shortlist);if(b?.dataset.jump){chooseDesign(b.dataset.jump);$('.studio').scrollIntoView({behavior:'smooth',block:'start'});}});
$('#reset').addEventListener('click',()=>{close();state.data[state.design]=defaults();renderDesktop();toast('此方案的演示已重置',true);});
$('#fullscreen').addEventListener('click',fullscreen);$('#exit-fullscreen').addEventListener('click',fullscreen);
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&state.immersive){state.immersive=false;state.direction=state.oldDirection||'landscape';document.body.classList.remove('immersive');$('#exit-fullscreen').hidden=true;fit();}});
let suppressUntil=0;
$('#screen').addEventListener('click',e=>{if(Date.now()<suppressUntil)return;const b=e.target.closest('button');if(!b){if(e.target.classList.contains('backdrop'))close();return;}if(b.dataset.app){open({type:'app',id:b.dataset.app});return;}const d=D(),a=b.dataset.action,v=b.dataset.value;
if(a==='close'){close();return;}if(a==='home'){close();return;}if(a==='library'){open({type:'library',query:''});return;}
if(a==='editorial')d.editorial=v;
if(a==='tile-edit')d.tileEdit=!d.tileEdit;
if(a==='tile-pin'){d.tileOrder=[v,...d.tileOrder.filter(x=>x!==v)];d.pinned=v;toast('已置顶'+apps.get(v).name,true);}
if(a==='compass')d.compass=v;
if(a==='compass-open'){open({type:'group',key:d.compass,query:''});return;}
if(a==='day'){d.day+=Number(v);d.period=((d.day+1)%4+4)%4;}
if(a==='period')d.period=Number(v);
if(a==='task-move'){const t=d.tasks.find(x=>x.id===v);if(t)t.stage=Math.max(0,Math.min(2,t.stage+Number(b.dataset.step)));}
if(a==='new-task'){if(d.tasks.length>=8){toast('演示最多容纳 8 件任务',true);return;}open({type:'new-task'});return;}
if(a==='station')d.station=d.station===v?null:v;
if(a==='atlas-clear')d.station=null;
if(a==='command-execute'){executeCommand();return;}
if(a==='index-group'){d.indexGroup=v;}
if(a==='scene')d.scene=v;
if(a==='card'){turnCard(Number(v));return;}
if(a==='card-index')d.card=Number(v);
if(a==='favorite'){d.favorites=d.favorites.includes(d.card)?d.favorites.filter(x=>x!==d.card):[...d.favorites,d.card];}
if(a==='favorites'){open({type:'favorites'});return;}
if(a==='favorite-jump'){d.card=Number(v);close();}
if(a)renderDesktop();
});
$('#screen').addEventListener('input',e=>{const d=D();if(e.target.id==='library-search'){state.overlay.query=e.target.value;$('#library-results').innerHTML=libraryResults(e.target.value,state.overlay.type==='group'?groups[state.overlay.key]:undefined);}if(e.target.id==='demo-note'){state.note=e.target.value;store.set('note',state.note);}if(e.target.id==='command-input'){d.command=e.target.value;$('#command-results').innerHTML=commandResults();}if(e.target.id==='index-search'){d.indexQuery=e.target.value;$('#index-results').innerHTML=indexResults();}});
$('#screen').addEventListener('submit',e=>{if(e.target.id!=='task-form')return;e.preventDefault();const title=$('#task-title').value.trim();if(!title){$('#task-title').setCustomValidity('请输入任务名称');$('#task-title').reportValidity();$('#task-title').setCustomValidity('');return;}const d=D();if(d.tasks.length>=8){toast('演示最多容纳 8 件任务',true);return;}d.tasks.push({id:'t'+Date.now(),title,app:$('#task-app').value,tag:'新任务',stage:0});close();renderDesktop();toast('已添加到待开始',true);});
let swipe=null;
$('#screen').addEventListener('pointerdown',e=>{if(e.button!==0||!e.target.closest('#swipe-card')||e.target.closest('button'))return;swipe={x:e.clientX,y:e.clientY};});
$('#screen').addEventListener('pointerup',e=>{if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;swipe=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4){turnCard(dx<0?1:-1);suppressUntil=Date.now()+300;}});
window.addEventListener('pointerup',()=>{swipe=null;});window.addEventListener('pointercancel',()=>{swipe=null;});
document.addEventListener('keydown',e=>{const input=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(e.key==='Escape'){if(state.overlay){close();e.preventDefault();}else if(state.immersive)fullscreen();return;}if(state.overlay&&e.key==='Tab'){const fields=$$('button,input,textarea,select',$('#overlays')).filter(x=>!x.disabled),first=fields[0],last=fields[fields.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}return;}if(e.target.id==='command-input'&&e.key==='Enter'){e.preventDefault();executeCommand();return;}if(input)return;if(e.key==='/'){e.preventDefault();open({type:'library',query:''});}if(!state.overlay&&state.design==='deck'&&['ArrowLeft','ArrowRight'].includes(e.key)){turnCard(e.key==='ArrowRight'?1:-1);e.preventDefault();}});
new ResizeObserver(fit).observe($('#stage'));window.addEventListener('resize',fit);window.addEventListener('orientationchange',()=>requestAnimationFrame(fit));render();
})();
